    let loopId = null;
    let audioCtx = null;

    function reset() {
      player = { x: 100, y: canvas.height / 2, vy: 0 };
      hazards = [];
      score = 0;
      phase = 'playing';
      keys = new Set();
      lastTime = performance.now();
    }

    // === BOOT ===============================================================
    reset();
```

