// === CONFIG =============================================================
const PLAYER_R = 6; // player dot radius in px
const GRAVITY = 800; // px/s^2, downward acceleration
const THRUST = -300; // impulse velocity change on tap (px/s)
const PIPE_W = 80; // pipe width
const PIPE_GAP = 200; // vertical gap size between pipe halves
const PIPE_SPEED = 200; // scrolling speed in px/s

// === STATE ==============================================================
const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');
const restartBtn = document.getElementById('restart');

let player = { x: 0, y: 0, vy: 0 }; // player position and vertical velocity
let hazards = []; // array of pipe objects
let score = 0;
let phase = 'playing'; // 'playing' | 'lost' | 'won'
let keys = new Set(); // active keys (e.g., space for thrust)
let lastTime = performance.now();
let loopId = null;
let audioCtx = null;

function reset() {
  // Initialize player in left side, vertically centered
  player.x = 100;
  player.y = canvas.height / 2;
  player.vy = 0;
  hazards = [];
  score = 0;
  phase = 'playing';
  keys = new Set();
  lastTime = performance.now();
}

// === BOOT ===============================================================
reset();

